from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol

from rasa.core.channels.voice_stream.call_recording.recording_encoder import (
    RECORDING_FILE_EXTENSION,
)


@dataclass
class RecordingReference:
    """Reference to a saved call recording."""

    provider: str
    bucket: str
    key: str
    uri: str
    content_type: str
    status: str = "available"


class RecordingStorage(Protocol):
    """Storage backend that persists an encoded call recording."""

    def upload(
        self, source: Path, conversation_id: str, call_id: str
    ) -> RecordingReference:
        """Persist the encoded recording and return a location reference.

        Args:
            source: Path to the encoded recording file.
            conversation_id: Conversation identifier used in the object name.
            call_id: Call identifier used in the object name.

        Returns:
            Location of the persisted recording.
        """
        ...


def _object_key(prefix: str, conversation_id: str, call_id: str) -> str:
    """Build the object storage key for a call recording."""
    normalized_prefix = prefix.strip("/")
    filename = (
        f"{_safe_key_part(conversation_id)}-{_safe_key_part(call_id)}"
        f".{RECORDING_FILE_EXTENSION}"
    )
    return f"{normalized_prefix}/{filename}" if normalized_prefix else filename


def _safe_key_part(value: str) -> str:
    return re.sub(r"[^A-Za-z0-9_.-]", "_", value)
